-- Offline lexical demonstration, identical source/query encoder. Not an ML model.
CREATE MACRO search.embed(content) AS [
    CASE WHEN contains(lower(content), 'savings') THEN 1.0 ELSE 0.1 END,
    CASE WHEN contains(lower(content), 'payments') THEN 1.0 ELSE 0.1 END,
    CASE WHEN contains(lower(content), 'credit') THEN 1.0 ELSE 0.1 END
]::FLOAT[3];

CREATE VIEW search.searchable AS
SELECT e.embedding_id, e.entity_id, e.embedding, e.embedding_model,
       e.embedding_model_version, p.product_name, p.description
FROM search.v_entity_embedding e
JOIN domain.v_product p ON e.entity_kind='PRODUCT' AND e.entity_id=p.product_id;

CREATE MACRO search.nearest(query_vector, k) AS TABLE
SELECT entity_id, product_name, description,
       array_cosine_similarity(embedding, query_vector::FLOAT[3]) AS similarity
FROM search.searchable
WHERE embedding_model='toy-lexical-v1'
ORDER BY similarity DESC, entity_id LIMIT k;

CREATE VIEW prediction.enriched AS
SELECT p.prediction_id, p.entity_id, c.display_name, p.prediction_value,
       p.model_key, p.model_version, p.prediction_dts, p.feature_observation_dts
FROM prediction.v_model_prediction p JOIN domain.v_customer c ON p.entity_id=c.customer_id;

CREATE MACRO prediction.training_at(at_dts) AS TABLE
SELECT f.entity_id, c.segment, f.value_numeric, f.observation_dts
FROM prediction.at_feature_value(at_dts) f
JOIN domain.at_customer(at_dts) c ON c.customer_id=f.entity_id
WHERE f.observation_dts <= at_dts::TIMESTAMPTZ;

CREATE VIEW semantic.column_catalogue AS
SELECT c.schema_name AS container_name, c.table_name, c.column_name,
       c.data_type, c.is_nullable, m.business_description, m.is_pii,
       m.is_sensitive, m.data_classification,
       'duckdb_columns' AS declared_type_source,
       CASE WHEN m.business_description IS NOT NULL THEN 'authored' ELSE 'missing' END AS description_source,
       m.business_description IS NOT NULL AS documentation_covered
FROM duckdb_columns() c
LEFT JOIN semantic.column_metadata m ON m.container_name=c.schema_name
 AND m.table_name=c.table_name AND m.column_name=c.column_name
WHERE c.database_name=current_database() AND c.schema_name IN
 ('domain','semantic','search','prediction','observability','memory');

CREATE VIEW semantic.data_product_manifest AS
SELECT p.product_id, p.product_version, p.trust_authoritative_producer,
       p.approved_entrypoint, p.approved_access_mode,
       max(o.object_identity) FILTER(WHERE o.resource_role='TRUST_MAP') AS trust_map,
       max(o.object_identity) FILTER(WHERE o.resource_role='MODULE_MAP') AS module_map,
       max(o.object_identity) FILTER(WHERE o.resource_role='OBJECT_CATALOGUE') AS object_catalogue,
       to_json(list(struct_pack(role:=o.resource_role, object_identity:=o.object_identity,
                               discovery_order:=o.discovery_order, is_required:=o.is_required)
                    ORDER BY o.discovery_order)) AS resources
FROM semantic.data_product_registry p JOIN semantic.data_product_orientation o USING(product_id)
GROUP BY p.product_id, p.product_version, p.trust_authoritative_producer, p.approved_entrypoint, p.approved_access_mode;

CREATE VIEW semantic.relationship_edges AS
SELECT source_entity, source_column, target_entity, target_column FROM semantic.table_relationship
UNION ALL
SELECT target_entity, target_column, source_entity, source_column FROM semantic.table_relationship;

-- Cycle-free and bounded; retain full ordered join predicates at every hop.
CREATE VIEW semantic.relationship_paths AS
WITH RECURSIVE paths AS (
 SELECT source_entity, target_entity, [source_entity,target_entity] AS visited,
        source_entity||'.'||source_column||' = '||target_entity||'.'||target_column AS join_path, 1 AS hops
 FROM semantic.relationship_edges
 UNION ALL
 SELECT p.source_entity, e.target_entity, list_append(p.visited,e.target_entity),
        p.join_path||' AND '||e.source_entity||'.'||e.source_column||' = '||e.target_entity||'.'||e.target_column, p.hops+1
 FROM paths p JOIN semantic.relationship_edges e ON p.target_entity=e.source_entity
 WHERE p.hops<4 AND NOT list_contains(p.visited,e.target_entity)
) SELECT source_entity,target_entity,visited,join_path,hops FROM paths;

CREATE VIEW semantic.access_edges AS
SELECT e.source_entity, a.object_identity AS source_object, e.source_column,
       e.target_entity, b.object_identity AS target_object, e.target_column
FROM semantic.relationship_edges e
JOIN semantic.access_object a ON a.represents_entity=e.source_entity AND a.is_agent_consumable AND a.access_role='PASSTHROUGH'
JOIN semantic.access_object b ON b.represents_entity=e.target_entity AND b.is_agent_consumable AND b.access_role='PASSTHROUGH';

CREATE VIEW semantic.access_relationship_paths AS
WITH RECURSIVE paths AS (
 SELECT source_entity,target_entity,source_object,target_object,
        [source_entity,target_entity] AS visited,
        source_object||'.'||source_column||' = '||target_object||'.'||target_column AS join_path, 1 AS hops
 FROM semantic.access_edges
 UNION ALL
 SELECT p.source_entity,e.target_entity,p.source_object,e.target_object,list_append(p.visited,e.target_entity),
        p.join_path||' AND '||e.source_object||'.'||e.source_column||' = '||e.target_object||'.'||e.target_column,p.hops+1
 FROM paths p JOIN semantic.access_edges e ON p.target_entity=e.source_entity
 WHERE p.hops<4 AND NOT list_contains(p.visited,e.target_entity)
) SELECT source_entity,target_entity,source_object,target_object,visited,join_path,hops FROM paths;

CREATE VIEW semantic.lineage_graph AS
SELECT DISTINCT source_table AS source_node, job_name AS target_node, 'produces' AS edge_type
FROM observability.data_lineage WHERE is_active
UNION
SELECT DISTINCT job_name, target_table, 'produces' FROM observability.data_lineage WHERE is_active;

CREATE VIEW semantic.lineage_run_latest AS
SELECT d.lineage_id,d.source_table,d.target_table,d.job_name,r.run_dts,r.run_status
FROM observability.data_lineage d LEFT JOIN observability.lineage_run r USING(lineage_id)
WHERE d.is_active
QUALIFY row_number() OVER(PARTITION BY d.lineage_id ORDER BY r.run_dts DESC,r.lineage_run_id DESC)=1;

CREATE VIEW observability.validation_run_latest AS
SELECT * FROM observability.validation_run
QUALIFY row_number() OVER(PARTITION BY product_prefix,producer_id ORDER BY completed_dts DESC,run_id DESC)=1;

-- Authoritative producer and latest PER AREA; newer runs need not cover old areas.
-- No evidence remains visible, and stale evidence cannot retain strong confidence.
CREATE VIEW observability.trust_map_evidence AS
WITH latest_area AS (
 SELECT a.*,r.evidence_expires_dts FROM observability.validation_area a
 JOIN observability.validation_run r USING(product_prefix,producer_id,run_id)
 QUALIFY row_number() OVER(PARTITION BY a.product_prefix,a.producer_id,a.scope_kind,a.scope_id
                          ORDER BY a.completed_dts DESC,a.run_id DESC)=1
)
SELECT a.product_prefix,a.producer_id,a.run_id,a.scope_kind,a.scope_id,a.area_status,
 CASE WHEN current_timestamp > coalesce(a.evidence_expires_dts,
      a.completed_dts + p.max_evidence_age_days * INTERVAL '1 day') THEN 'unknown' ELSE a.confidence END AS confidence,
 a.checks_expected,a.checks_ran,a.passed_count,a.failed_count,a.error_count,
 a.critical_failure_count,a.error_failure_count,
 a.checks_ran::DOUBLE/nullif(a.checks_expected,0) AS coverage,
 CASE WHEN current_timestamp > coalesce(a.evidence_expires_dts,a.completed_dts+p.max_evidence_age_days*INTERVAL '1 day')
      THEN 'Evidence is stale.' ELSE a.open_gaps END AS open_gaps,
 CASE WHEN current_timestamp > coalesce(a.evidence_expires_dts,a.completed_dts+p.max_evidence_age_days*INTERVAL '1 day')
      THEN 'Re-run the validator; disclose unknown confidence.' ELSE a.recommended_action END AS recommended_action,
 a.completed_dts
FROM latest_area a JOIN semantic.data_product_registry p ON p.product_id=a.product_prefix
 AND (p.trust_authoritative_producer=a.producer_id OR nullif(p.trust_authoritative_producer,'') IS NULL)
UNION ALL
SELECT p.product_id,p.trust_authoritative_producer,NULL,'PRODUCT',p.product_id,'no-evidence','unknown',
       0,0,0,0,0,0,0,NULL,'No published area evidence.','Run the validator before reporting confidence.',NULL
FROM semantic.data_product_registry p WHERE NOT EXISTS
 (SELECT 1 FROM latest_area a WHERE a.product_prefix=p.product_id
 AND (a.producer_id=p.trust_authoritative_producer OR nullif(p.trust_authoritative_producer,'') IS NULL));

CREATE VIEW observability.trust_map AS
SELECT e.product_prefix,e.producer_id,e.run_id,e.scope_kind,e.scope_id,e.area_status,e.confidence,
       e.checks_expected,e.checks_ran,e.passed_count,e.failed_count,e.error_count,
       e.critical_failure_count,e.error_failure_count,e.coverage,e.open_gaps,
       CASE WHEN nullif(p.trust_authoritative_producer,'') IS NULL
            THEN 'No designated producer: cautious per-area fallback. '||coalesce(e.recommended_action,'Designate one producer.')
            ELSE e.recommended_action END AS recommended_action,e.completed_dts
FROM observability.trust_map_evidence e JOIN semantic.data_product_registry p ON p.product_id=e.product_prefix
QUALIFY row_number() OVER(PARTITION BY e.product_prefix,e.scope_kind,e.scope_id ORDER BY
 CASE e.confidence WHEN 'unknown' THEN 0 WHEN 'weak' THEN 1 WHEN 'partial' THEN 2 ELSE 3 END,
 e.completed_dts DESC,e.run_id DESC,e.producer_id)=1;

