rrent consumable surfaces.' WHEN 'relationship_type' THEN 'FOREIGN_KEY or semantic association.' WHEN 'is_mandatory' THEN 'Whether each source row must resolve.' WHEN 'object_identity' THEN 'Verbatim database resource name.' WHEN 'object_type' THEN 'VIEW in this binding.' WHEN 'access_role' THEN 'BASE, PASSTHROUGH or COMPOSITE.' WHEN 'represents_entity' THEN 'Entity represented; null for composite objects.' WHEN 'object_grain' THEN 'One row represents this unit.' WHEN 'is_agent_consumable' THEN 'Whether this is a public analytical surface.' WHEN 'resolves_to_object' THEN 'Base object exposed by a passthrough.' WHEN 'consumer_audience' THEN 'AGENT, BI or ALL on CONSUMER_VIEW objects; null on every other object type.' WHEN 'access_semantics' THEN 'FULL_HISTORY, CURRENT_ONLY or POINT_IN_TIME; null when the entity declares no history.' WHEN 'access_note' THEN 'Filtering and safe-use guidance.' WHEN 'access_composition_id' THEN 'Composite and member identity.' WHEN 'composite_object' THEN 'Exact joined view.' WHEN 'member_entity' THEN 'Qualified catalogued member.' WHEN 'member_role' THEN 'ANCHOR or joined-member role.' WHEN 'join_path' THEN 'Explicit join predicate; empty for anchor.' WHEN 'is_grain_contributor' THEN 'Whether member changes row grain.' WHEN 'object_role' THEN 'Controlled discovery role.' WHEN 'usage_guidance' THEN 'How an agent should use this object.' WHEN 'resource_role' THEN 'One resource role per row.' WHEN 'discovery_order' THEN 'Ascending navigation order; trust precedes analytics.' WHEN 'is_required' THEN 'Missing required resources fail conformance.' WHEN 'standard_value' THEN 'Naming token or pattern.' WHEN 'meaning' THEN 'Meaning of the convention.' WHEN 'applies_to' THEN 'Object or column scope.' WHEN 'metric_name' THEN 'Performance dimension, separate from predictions.' WHEN 'metric_description' THEN 'Meaning and exclusions.' WHEN 'unit' THEN 'Normalised unit and bounds.' WHEN 'aggregation_type' THEN 'Aggregation rule.' WHEN 'grain_descripti