INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-OBSERVABILITY-001', 1, 'Evidence separation', 'Separate quality, lineage, execution and validation evidence', 'Server platform; embedded file; external serving application, according to capability.', 'DEC-QUALITY-STORAGE=observability: data quality time series, validation coverage, flow definitions and executions are separate entities.', 'DEC-TIMESTAMP-ZONE=zone-aware UTC. Capability gaps remain visible in the trust map.', 'ACCEPTED', 'ARCHITECTURE', 'observability', 'reference-implementation', 'examples/customer360-duckdb', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-OBSERVABILITY-002', 1, 'Retention', 'Separate quality, lineage, execution and validation evidence', 'Server platform; embedded file; external serving application, according to capability.', 'DEC-AUDIT-RETENTION uses an explicit synthetic-demo policy: definitions for product life; events 90 days; validation 365 days. Operator executes archival, never a hidden build job.', 'DEC-TIMESTAMP-ZONE=zone-aware UTC. Capability gaps remain visible in the trust map.', 'ACCEPTED', 'ARCHITECTURE', 'observability', 'reference-implementation', 'examples/customer360-duckdb', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-OBSERVABILITY-003', 1, 'Optional graph facets', 'Separate quality, lineage, execution and validation evidence', 'Server platform; embedded file; external serving application, according to capability.', 'Graph-native and column-lineage facets are omitted. Table-level active lineage remains discoverable in Semantic. No external Graph Explorer dependency.', 'DEC-TIMESTAMP-ZONE=zone-aware UTC. Capability gaps remain visible in the trust map.', 'ACCEPTED', 'ARCHITECTURE', 'observability', 'reference-implementation', 'examples/customer360-duckdb', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
