INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-MEMORY-002', 1, 'Runtime privacy', 'Versioned design rationale and scoped agent process continuity', 'Server platform; embedded file; external serving application, according to capability.', 'All runtime entities require scope level and owner. Synthetic runtime is self-contained here; production host must deny direct SQL and enforce identity, or store private runtime in a separate protected file.', 'DEC-TIMESTAMP-ZONE=zone-aware UTC. Capability gaps remain visible in the trust map.', 'ACCEPTED', 'ARCHITECTURE', 'memory', 'reference-implementation', 'examples/customer360-duckdb', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
