INSERT INTO memory.business_glossary (term, term_category, definition, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('Process context', 'BUSINESS_RULE', 'Task metadata excluding business query results.', 'memory', 'reference-implementation', 'examples/customer360-duckdb', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-ACCESS-001', 1, 'Three logical tiers', 'Portable embedded product', 'See rationale for considered choices.', 'READ and AGENT have independent lifecycles; only AGENT appends runtime Memory and Observability. ADMIN maintains all. Unlike single consumer roles or per-user grants, a host maps these tiers to authenticated actions. DuckDB itself cannot enforce them.', 'External security remains a deployment obligation.', 'ACCEPTED', 'SECURITY', 'memory', 'reference-implementation', 'examples/customer360-duckdb', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-DISCOVERY-001', 1, 'Name-only bootstrap', 'Portable embedded product', 'See rationale for considered choices.', 'Given customer360, read semantic.data_product_registry then ordered orientation and generated manifest. Trust precedes analytical use; approved domain.v_customer is the initial business entrypoint. Product-less discovery lists the registry.', 'External security remains a deployment obligation.', 'ACCEPTED', 'ARCHITECTURE', 'semantic', 'reference-implementation', 'examples/customer360-duckdb', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-DOMAIN-004', 1, 'Placement and portability', 'Portable embedded product', 'See rationale for considered choices.', 'One product file with six co-located schemas preserves self-containment. Environment changes only the file path/catalogue. Separate files are optional for private runtime. Default storage is internal; external Parquet requires its own governed lifecycle.', 'External security remains a deployment obligation.', 'ACCEPTED', 'ARCHITECTURE', 'domain', 'reference-implementation', 'examples/customer360-duckdb', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-SEMANTIC-004', 1, 'Reusable SQL delivery', 'Portable embedded product', 'See rationale for considered choices.', 'A small explicit Python model generates plain SQL with shared temporal fields and complete registration. The checked build.sql runs in CLI/JDBC without Python. No Jinja dependency or DDL parsing during discovery.', 'External security remains a deployment obligation.', 'ACCEPTED', 'ARCHITECTURE', 'semantic', 'reference-implementation', 'examples/customer360-duckdb', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.query_cookbook (recipe_id, recipe_title, use_case, target_module, query_template, complexity, is_batch, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('QC-SEMANTIC-002', 'Discover the ERD', 'Render registered relationships', 'SEMANTIC', 'SELECT source_entity, source_column, target_entity, target_column FROM semantic.v_table_relationship ORDER BY relationship_id', 'SIMPLE', FALSE, 'semantic', 'reference-implementation', 'examples/customer360-duckdb', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
