INSERT INTO memory.implementation_note (note_id, note_title, note_content, note_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('IN-MEMORY-001', 'Runtime isolation boundary', 'File access exposes all synthetic runtime records. Production private runtime requires an authenticated host or a separate protected file.', 'SECURITY', 'memory', 'reference-implementation', 'examples/customer360-duckdb', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
-- Record actual physical deployment audit instants.
UPDATE domain.customer_keymap SET created_dts=current_timestamp,updated_dts=current_timestamp;
UPDATE domain.customer SET created_dts=current_timestamp,updated_dts=current_timestamp;
UPDATE domain.product_keymap SET created_dts=current_timestamp,updated_dts=current_timestamp;
UPDATE domain.product SET created_dts=current_timestamp,updated_dts=current_timestamp;
UPDATE domain.account_keymap SET created_dts=current_timestamp,updated_dts=current_timestamp;
UPDATE domain.account SET created_dts=current_timestamp,updated_dts=current_timestamp;
UPDATE domain.transaction_keymap SET created_dts=current_timestamp,updated_dts=current_timestamp;
UPDATE domain.transaction SET created_dts=current_timestamp,updated_dts=current_timestamp;
